                  {item.title}
                </div>
                <div className="text-[11px] text-slate-400 mt-0.5">{item.desc}</div>
              </button>
            ))}
          </div>
        </div>

        {/* Registro de Mutações de Código */}
        <div>
          <div className="flex items-center gap-1.5 mb-2.5 text-cyan-400 font-semibold uppercase tracking-wider text-[10px]">
            <GitCommit size={12} />
            <span>Últimas Modificações de Código</span>
          </div>

          {recentChanges.length === 0 ? (
            <div className="p-4 rounded-xl bg-slate-900/50 border border-slate-800/80 text-center text-slate-500 text-[11px]">
              Nenhum novo código gerado ainda nesta sessão. Peça algo à Izzy no chat!
            </div>
          ) : (
            <div className="space-y-2">
              {recentChanges.map((change, idx) => (
                <div
                  key={idx}
                  className="p-2.5 rounded-xl bg-slate-900/90 border border-cyan-500/20 text-slate-300 space-y-1"
                >
                  <div className="flex items-center gap-1.5 text-cyan-300 font-mono text-[11px]">
                    <FileCode size={12} />
                    <span className="truncate">{change.path}</span>
                  </div>
                  <p className="text-[11px] text-slate-400">{change.message}</p>
                  <div className="text-[9px] text-slate-500">
                    {new Date(change.timestamp).toLocaleTimeString()}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </aside>
  );
}

'use client';

import React from 'react';
import { Sparkles, Code2, Rocket, Brain, CheckCircle2 } from 'lucide-react';

interface IzzyAvatarProps {
  mood?: 'idle' | 'thinking' | 'coding' | 'deploying' | 'proud';
  size?: 'sm' | 'md' | 'lg' | 'xl';
}

export default function IzzyAvatar({ mood = 'idle', size = 'md' }: IzzyAvatarProps) {
  const sizeClasses = {
    sm: 'w-10 h-10',
    md: 'w-16 h-16',
    lg: 'w-24 h-24',
    xl: 'w-32 h-32',
  }[size];

  const iconSizes = {
    sm: 14,
    md: 20,
    lg: 28,
    xl: 36,
  }[size];

  return (
    <div className="relative inline-flex items-center justify-center select-none group">
      {/* Halo de energia animado */}
      <div
        className={`absolute inset-0 rounded-full blur-md transition-all duration-700 ${
          mood === 'coding'
            ? 'bg-gradient-to-tr from-cyan-500 via-pink-500 to-amber-400 opacity-90 animate-spin'
            : mood === 'deploying'
            ? 'bg-gradient-to-r from-emerald-400 to-cyan-500 opacity-90 animate-pulse'
            : mood === 'thinking'
            ? 'bg-gradient-to-r from-violet-600 to-fuchsia-600 opacity-80 animate-pulse'
            : 'bg-gradient-to-r from-pink-500 via-purple-500 to-cyan-400 opacity-70 animate-glow'
        }`}
      />

      {/* Círculo Principal do Avatar */}
      <div
        className={`relative ${sizeClasses} rounded-full bg-slate-950 border-2 transition-all duration-300 flex items-center justify-center overflow-hidden shadow-2xl ${
          mood === 'coding'
            ? 'border-cyan-400 ring-2 ring-cyan-400/50'
            : mood === 'deploying'
            ? 'border-emerald-400 ring-2 ring-emerald-400/50'
            : mood === 'thinking'
            ? 'border-purple-400 ring-2 ring-purple-400/50'
            : 'border-pink-400 ring-2 ring-pink-400/40'
        }`}
      >
        {/* Fundo Cibernético com grid sutil */}
        <div className="absolute inset-0 bg-[radial-gradient(#ec4899_1px,transparent_1px)] [background-size:8px_8px] opacity-20" />

        {/* Rosto / Ícone da Izzy */}
        <div className="relative z-10 flex flex-col items-center justify-center">
          {mood === 'coding' ? (
            <div className="flex flex-col items-center animate-bounce">
              <Code2 size={iconSizes} className="text-cyan-400 drop-shadow-[0_0_8px_rgba(34,211,238,0.8)]" />
            </div>
          ) : mood === 'deploying' ? (
            <div className="flex flex-col items-center animate-pulse">
              <Rocket size={iconSizes} className="text-emerald-400 drop-shadow-[0_0_8px_rgba(52,211,153,0.8)]" />
            </div>
          ) : mood === 'thinking' ? (
            <div className="flex flex-col items-center animate-pulse">
              <Brain size={iconSizes} className="text-purple-300 drop-shadow-[0_0_8px_rgba(216,180,254,0.8)]" />
            </div>
          ) : mood === 'proud' ? (
            <div className="flex flex-col items-center">
              <CheckCircle2 size={iconSizes} className="text-pink-400 drop-shadow-[0_0_8px_rgba(244,114,182,0.8)]" />
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center">
              {/* Olhos cibernéticos expressivos da Izzy */}
              <div className="flex items-center gap-2 mb-1">
                <span className="w-2.5 h-2.5 rounded-full bg-cyan-400 shadow-[0_0_8px_#22d3ee] animate-pulse" />
                <span className="w-2.5 h-2.5 rounded-full bg-pink-400 shadow-[0_0_8px_#f472b6] animate-pulse" />
              </div>
              <Sparkles size={iconSizes * 0.7} className="text-pink-300 opacity-90 animate-float" />
            </div>
          )}
        </div>
      </div>

      {/* Badge de status flutuante */}
      <span
        className={`absolute -bottom-1 -right-1 px-1.5 py-0.5 text-[9px] font-bold rounded-full uppercase tracking-wider shadow-lg border ${
          mood === 'coding'
            ? 'bg-cyan-950 text-cyan-300 border-cyan-500 animate-pulse'
            : mood === 'deploying'
            ? 'bg-emerald-950 text-emerald-300 border-emerald-500'
            : mood === 'thinking'
            ? 'bg-purple-950 text-purple-300 border-purple-500'
            : 'bg-pink-950 text-pink-300 border-pink-500'
        }`}
      >
        {mood === 'coding'
          ? 'DEV'
          : mood === 'deploying'
          ? 'VERCEL'
          : mood === 'thinking'
          ? 'PENSANDO'
          : 'IZZY'}
      </span>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import {
  Send,
  Sparkles,
  Settings,
  Cpu,
  RefreshCw,
  Rocket,
  CheckCircle2,
  AlertTriangle,
  Code2,
  GitCommit,
  Terminal,
  ExternalLink,
} from 'lucide-react';
import confetti from 'canvas-confetti';
import IzzyAvatar from './IzzyAvatar';
import SettingsModal, { AppConfig } from './SettingsModal';
import EvolutionSidebar from './EvolutionSidebar';
import { ChatMessage } from '@/lib/types';

export default function IzzyInterface() {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isEvolutionOpen, setIsEvolutionOpen] = useState(false);

  const [izzyMood, setIzzyMood] = useState<'idle' | 'thinking' | 'coding' | 'deploying' | 'proud'>('idle');
  const [recentChanges, setRecentChanges] = useState<{ path: string; message: string; timestamp: number }[]>([]);

  const [activeDeploy, setActiveDeploy] = useState<{
    status: 'building' | 'ready' | 'idle';
    path?: string;
    message?: string;
    timer?: number;
  }>({ status: 'idle' });

  const [config, setConfig] = useState<AppConfig>({
    geminiKey: '',
    githubToken: '',
    githubRepo: '',
    githubBranch: 'main',
    vercelToken: '',
    vercelProjectId: '',
  });

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Carregar configurações locais
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem('izzy_config');
      if (stored) {
        try {
          setConfig(JSON.parse(stored));
        } catch {}
      }

      // Mensagem inicial de boas-vindas da Izzy
      setMessages([
        {
          id: 'welcome',
          role: 'assistant',
          content: `Olá! Eu sou a **Izzy**! ✨\n\nEu não sou apenas um chatbot comum: **eu sou o próprio código desta aplicação**! Se você me pedir algo que eu ainda não tenho (um bloco de notas, um tema neon, um tocador de música lo-fi, uma calculadora ou qualquer componente), eu vou abrir meu código, programar a mim mesma, fazer o commit no GitHub e mandar o Vercel compilar a novidade!\n\nComo posso evoluir ou ajudar você hoje?`,
          timestamp: Date.now(),
        },
      ]);
    }
  }, []);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, izzyMood]);

  const handleSendMessage = async (textToSend?: string) => {
    const text = (textToSend || input).trim();
    if (!text || isLoading) return;

    const userMsg: ChatMessage = {
      id: `user-${Date.now()}`,
      role: 'user',
      content: text,
      timestamp: Date.now(),
    };

    setMessages((prev) => [...prev, userMsg]);
    setInput('');
    setIsLoading(true);
    setIzzyMood('thinking');

    try {
      const res = await fetch('/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          messages: [...messages, userMsg],
          userApiKey: config.geminiKey,
          userGithubToken: config.githubToken,
          userRepo: config.githubRepo,
          userBranch: config.githubBranch,
          userVercelToken: config.vercelToken,
          userProjectId: config.vercelProjectId,
        }),
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || 'Erro na resposta do servidor.');
      }

      // Se a Izzy fez alterações de código
      if (data.hasModifiedCode) {
        setIzzyMood('coding');
        setTimeout(() => setIzzyMood('deploying'), 1500);

        // Registrar mudanças recentes
        const modifiedFiles = data.toolCalls
          ?.filter((tc: any) => tc.name === 'write_repository_file' && tc.status === 'success')
          .map((tc: any) => ({
            path: tc.args.path,
            message: tc.args.commitMessage,
            timestamp: Date.now(),
          })) || [];

        if (modifiedFiles.length > 0) {
          setRecentChanges((prev) => [...modifiedFiles, ...prev]);
          setActiveDeploy({
            status: 'building',
            path: modifiedFiles[0].path,
            message: modifiedFiles[0].message,
          });

          // Disparar timer simulado de compilação da Vercel (geralmente 40s)
          setTimeout(() => {
            setActiveDeploy((prev) => ({ ...prev, status: 'ready' }));
            setIzzyMood('proud');
            try {
              confetti({ particleCount: 100, spread: 70, origin: { y: 0.6 } });
            } catch {}
          }, 40000);
        }
      } else {
        setIzzyMood('idle');
      }

      const assistantMsg: ChatMessage = {
        id: `assistant-${Date.now()}`,
        role: 'assistant',
        content: data.reply,
        timestamp: Date.now(),
        toolCalls: data.toolCalls,
        deployStatus: data.hasModifiedCode ? 'building' : undefined,
      };

      setMessages((prev) => [...prev, assistantMsg]);
    } catch (err: any) {
      setIzzyMood('idle');
      setMessages((prev) => [
        ...prev,
        {
          id: `err-${Date.now()}`,
          role: 'assistant',
          content: `⚠️ Ops! Tive um problema ao processar seu pedido:\n\n\`${err.message}\`\n\nCertifique-se de configurar a **Gemini API Key** e o **GitHub Token** no botão de engrenagem ⚙️ no topo!`,
          timestamp: Date.now(),
        },
      ]);
    } finally {
      setIsLoading(false);
    }
  };

  const triggerReload = () => {
    try {
      confetti({ particleCount: 80, spread: 60 });
